import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t,o,c as _,a3 as e}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/45-授时第三十五.md","filePath":"books/yan-tie-lun/45-授时第三十五.md","lastUpdated":1794316978000}'),l={name:"books/yan-tie-lun/45-授时第三十五.md"};function n(i,a,s,r,c,d){return o(),_("div",null,[...a[0]||(a[0]=[e('<p>授时第三十五 【题解】</p><p>本篇讨论如何对待农民贫困问题。大夫首先指出，部分民众贫穷是由于他们懒惰奢侈造成的，朝廷不应该同情此类懒惰之人。贤良指出，民众的勤懒完全有赖于朝廷的政治教化。大夫进一步申辩，以为部分民众贫穷困乏是由于他们干活不卖力，用财不节制。贤良按照孔子提出的从“庶之”“富之”到“教之”的治民路线，主张先让民众富裕起来，再对他们进行礼义教化。大夫诉苦说，朝廷已经实施劝农、赈贷政策，可是仍然解决不了民众贫穷问题。贤良认为，鼓励农耕关键在于不误农时，而不是搞一些悬挂青旗、鞭策土牛的劝农形式。</p><p>大夫曰：“共其地[(1)]，居是世也[(2)]，非有灾害疾疫，独以贫穷，非惰则奢也；无奇业旁入[(3)]，而犹以富给，非俭则力也。今曰施惠悦尔[(4)]，行刑不乐；则是闵无行之人[(5)]，而养惰奢之民也。故妄予不为惠[(6)]，惠恶者不为仁[(7)]。”</p><p>【注释】</p><p>[(1)]共其地：共同居住在一个地方。</p><p>[(2)]居是世：处于同一个时代。</p><p>[(3)]奇业：指农工商以外的其他产业。旁入：额外收入。</p><p>[(4)]曰：原作“日”，据王利器说校改。</p><p>[(5)]闵：同“悯”，同情。无行之人：品行恶劣、懒惰奢侈的人。</p><p>[(6)]妄予：胡乱赐予。惠：恩惠。</p><p>[(7)]惠恶：施惠给恶人。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“共同居住在一个地方，处于同一个时代，如果不是遇到天灾、疾病、瘟疫，唯独有少数人贫穷，那么这些人不是因为懒惰就是由于奢侈；没有特殊产业和额外收入，而仍然生活富裕，那么这些人不是因为勤俭就是由于力耕。如今你说什么‘施予恩惠是令人高兴的事，执行刑杀并不让人快乐’；这是同情品行恶劣之人，养活懒惰奢侈之民。所以，胡乱赐予不能叫恩惠，施惠给恶人不能叫仁爱。”</p><p>贤良曰：“三代之盛无乱萌[(1)]，教也；夏、商之季世无顺民[(2)]，俗也。是以王者设庠序[(3)]，明教化，以防道其民[(4)]，及政教之洽[(5)]，性仁而喻善[(6)]。故礼义立，则耕者让于野；礼义坏，则君子争于朝[(7)]。人争则乱，乱则天下不均，故或贫或富。富则仁生，赡则争止[(8)]。昏暮叩人门户，求水火，贪夫不恡[(9)]，何则？所饶也。夫为政而使菽粟如水火[(10)]，民安有不仁者乎！”</p><p>【注释】</p><p>[(1)]三代：夏、商、周。萌：通“民”。</p><p>[(2)]季世：末世。顺民：逆来顺受的良民。</p><p>[(3)]庠（xiánɡ）：周代学校。序：商代学校。</p><p>[(4)]防道：预防疏导。道，同“導”（导）。</p><p>[(5)]洽：和谐。</p><p>[(6)]喻：知晓。</p><p>[(7)]君子争于朝：《战国策·秦策上》：“争名者于朝。”</p><p>[(8)]赡则争止：赡，富足。“则”下原有“民”字，据张敦仁说校删。</p><p>[(9)]贪夫：贪婪的人。恡：通“吝”，吝啬。</p><p>[(10)]菽粟：菽是豆，粟是谷子。菽粟泛指粮食。《孟子·尽心上》：“民非水火不生活，昏暮叩人之门户，求水火，无弗与者，至足矣。圣人治天下，使有菽粟如水火。菽粟如水火，而民焉有不仁者乎？”</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“夏、商、周三代兴盛之际没有叛乱民众，这是教化的结果；夏、商末世没有顺从民众，这是出于末世的风俗。因此王者设立学校，宣明王道教化，用来预防疏导民众，等到政治教化和谐的时候，人民品性就会变为仁义，知道什么是善。因此，如果礼义得以确立，那么耕田的人就会在田野礼让；如果礼义败坏，那么君子就会争于朝廷。人人相争，社会就陷入混乱；社会混乱，就会导致天下财富不平均；因此有人贫穷，有人富裕。富裕就容易产生仁义之心，丰足就会使争夺停止。薄暮黄昏时去敲人门户，向人求借水火，即使是贪婪的人也不会吝啬，这是为什么呢？是由于经济富饶啊。执政的人如果使粮食像水火一样充足，那么民众哪里会有不仁的呢！”</p><p>大夫曰：“博戏驰逐之徒[(1)]，皆富人子弟，非不足者也。故民饶则僭侈[(2)]，富则骄奢，坐而委蛇[(3)]，起而为非，未见其仁也。夫居事不力[(4)]，用财不节，虽有财如水火，穷乏可立而待也[(5)]。有民不畜[(6)]，有司虽助之耕织，其能足之乎？”</p><p>【注释】</p><p>[(1)]博戏：古代的一种棋戏。驰逐：驱马追逐，即赛马。</p><p>[(2)]僭（jiàn）：越礼。侈：奢侈。</p><p>[(3)]委蛇（yí）：从容自得的样子。</p><p>[(4)]居事不力：办事不尽力。</p><p>[(5)]立：立即。</p><p>[(6)]畜：通“蓄”，储蓄。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“下棋赌博、驱马追逐的人，都是富人子弟，并不是衣食不足的人。因此民众丰足就会僭越礼制，富裕就会骄傲奢侈，他们坐下来从容自得，站起来就为非作歹，没有见到过他们有什么仁义举动。办事不尽力，用财不节制，即使家财如同水火一般多，贫穷困乏也会指日可待的。民众不从事储蓄，主管官员即使帮助他们耕田织布，他们能够富足吗？”</p><p>贤良曰：“周公之相成王也[(1)]，百姓饶乐[(2)]，国无穷人[(3)]，非代之耕织也。易其田畴[(4)]，薄其税敛，则民富矣。上以奉君亲[(5)]，下无饥寒之忧，则教可成也。《语》曰[(6)]：‘既富矣，又何加焉？曰，教之。’[(7)]教之以德[(8)]，齐之以礼，则民徙义而从善[(9)]，莫不入孝出悌，夫何奢侈暴慢之有？管子曰：‘仓廪实而知礼节，百姓足而知荣辱。’[(10)]故富民易与适礼[(11)]。”</p><p>【注释】</p><p>[(1)]相：辅佐。</p><p>[(2)]饶乐：富饶快乐。</p><p>[(3)]国无穷人：“穷”下原有“乏”字，据卢文弨、王先谦说校删。</p><p>[(4)]易：修治。田畴：田地。《孟子·尽心上》：“易其田畴，薄其税敛，民可使富也。”</p><p>[(5)]奉：事奉。君：君主。亲：父母双亲。</p><p>[(6)]《语》：《论语》。</p><p>[(7)]既富矣，又何加焉？曰，教之：见于《论语·子路》。加，再做什么。</p><p>[(8)]教之：此二字原脱，据王利器说校补。《论语·为政》：“道之以德，齐之以礼，有耻且格。”</p><p>[(9)]徙义：向正义迁移。原作“从义”，据王利器说校改。</p><p>[(10)]仓廪实而知礼节，百姓足而知荣辱：见于《管子·牧民》。</p><p>[(11)]富民：原本“故”下无“富”字，据王利器说校补。适礼：向往礼义。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“周公辅佐成王时，老百姓丰饶快乐，国家没有穷人，周公并没有代替老百姓耕田织布。让民众修治田地，减轻他们的赋税，这样民众就自然富足了。老百姓对上可以事奉君主和父母双亲，对下没有饥寒之忧，这样教化就可以成功。《论语》说：‘老百姓已经富裕了，又该做什么呢？孔子说，教化他们。’用道德教化他们的思想，用礼仪整齐他们的行为，那么民众就会向往礼义追随善良，没有人不做到进家孝顺父母出门尊敬兄长，这样哪里会有什么奢侈、粗暴、怠慢的事？管仲说：‘仓库储满粮食，民众就会知道礼节；老百姓丰衣足食，就会知道荣辱。’所以富裕的民众容易向往礼义。”</p><p>大夫曰：“县官之于百姓，若慈父之于子也：忠焉能勿诲乎？爱之而勿劳乎[(1)]？故春亲耕以劝农[(2)]，赈贷以赡不足[(3)]，通滀水[(4)]，出轻系[(5)]，使民务时也。蒙恩被泽，而至今犹以贫困，其难与适道若是夫[(6)]！”</p><p>【注释】</p><p>[(1)]忠焉能勿诲乎？爱之而勿劳乎：见于《论语·宪问》，但语序颠倒。诲，教诲。而，读为“能”。</p><p>[(2)]亲耕：古代有天子藉田制度，在立春之日亲耕，以此鼓励天下民众勤于耕种。劝：劝勉。</p><p>[(3)]赈贷：赈济借贷。赡：补助。</p><p>[(4)]滀（chù）水：积水。</p><p>[(5)]出轻系：中国古代在冬天行刑，进入来年孟夏以后，将那些来不及行刑的轻罪犯人予以释放。轻系，犯轻罪而被囚系的人。</p><p>[(6)]难与适道：难以教他们走上正道。若是：像这样。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“朝廷对于老百姓，就像慈父对待子女一样：对他忠心，能不教诲他吗？对他疼爱，能不让他勤劳吗？因此立春季节，天子亲耕籍田来劝勉农夫，赈济借贷来补助那些衣食不足的人，疏通积水，放出牢房中罪轻的犯人，以便让民众抓紧农时。老百姓蒙受天子的恩泽，但至今仍然贫困，让他们走上正道是如此的困难啊！”</p><p>贤良曰：“古者，春省耕以补不足[(1)]，秋省敛以助不给[(2)]。民勤于财则贡赋省[(3)]，民勤于力则功筑罕[(4)]。为民爱力[(5)]，不夺须臾[(6)]。故召伯听断于甘棠之下[(7)]，为妨农业之务也[(8)]。今时雨澍泽[(9)]，种悬而不得播[(10)]，秋稼零落乎野而不得收。田畴赤地[(11)]，而停落成市[(12)]，发春而后[(13)]，悬青幡而策土牛[(14)]，殆非明主劝耕稼之意，而春令之所谓也[(15)]。”</p><p>【注释】</p><p>[(1)]省耕：省视春耕情况。补不足：补助农具、种子的不足。《孟子·梁惠王下》：“春省耕而补不足，秋省敛而助不给。”</p><p>[(2)]省敛：省视秋收状况。助不给：补助缺粮的不足。</p><p>[(3)]勤：枯竭。省：减轻。</p><p>[(4)]功筑罕：原作“功业牢”，据王利器说校改。功筑，土木徭役。罕，罕用。</p><p>[(5)]爱力：爱惜劳力。</p><p>[(6)]须臾：片刻时光。</p><p>[(7)]召伯听断于甘棠之下：这是关于《诗经·召南·甘棠》的故事。《韩诗外传》载：“昔者，周道之盛，邵伯在朝，有司请营邵以居，邵伯曰：‘嗟！以吾一身而劳百姓，此非吾先君文王之志也。’于是出就蒸庶于阡陌陇亩之间而听断焉。邵伯暴处远野，庐于树下。百姓大说，耕桑者倍力以劝。于是岁大稔，民给家足。其后在位者骄奢，不恤元元，税赋繁数，百姓困乏，耕桑失时。于是诗人见邵伯之所休息树下，美而歌之。《诗》曰：‘蔽茀甘棠，勿剪勿伐，召伯所茇。’此之谓也。”召伯，召公奭。</p><p>[(8)]妨：妨碍。</p><p>[(9)]澍（shù）泽：雨水滋润万物。澍，时雨。</p><p>[(10)]悬：悬挂。</p><p>[(11)]赤地：自然灾害造成田地寸草不生。</p><p>[(12)]停落：一作“亭落”，村落。</p><p>[(13)]发春：开春。</p><p>[(14)]悬青幡（fān）：悬挂青色的旗幡。策土牛：鞭打泥土雕塑的牛。按，悬青幡，策土牛，是中国古代鼓励农耕的一种宗教仪式。</p><p>[(15)]春令：颁布春耕令，表示劝勉农耕。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“古时候，到了春天，官员省视春耕，补助农夫工具、种子的不足，到了秋天，官员省视秋收，补助粮食歉收的农户。民众财源枯竭，就减少赋税；民众劳力缺少，就减少土木徭役。为民众爱惜劳力，不争夺农夫片刻时光。因此，西周召伯在甘棠树下听讼断案，他是担心妨碍农业事务啊。如今时雨滋润万物，可是农夫的种子悬挂在墙上而不能及时播种，秋天庄稼凋落在田野里而得不到收获。在荒年田地寸草不生，村落却成为集市，开春之后，官府悬挂青色旗幡，鞭策泥土雕塑的牛，这恐怕不是英明君主劝勉耕稼的本意，也不符合朝廷颁布春耕令的精神。”</p>',87)])])}const y=t(l,[["render",n]]);export{f as __pageData,y as default};
